            if (n < 0) return null
            var m0: String? = null
            var m1: ObjectFit? = null
            var m2: Boolean? = null
            repeat(n) {
                when (r.key()) {
                    "trackId" -> if (r.isNull()) r.skip() else m0 = r.string() ?: return null
                    "objectFit" -> if (r.isNull()) r.skip() else m1 = ObjectFit.read(r) ?: return null
                    "mirror" -> if (r.isNull()) r.skip() else m2 = r.bool() ?: return null
                    else -> r.skip()
                }
            }
            return RtcVideoParams(trackId = m0, objectFit = m1, mirror = m2)
        }
    }
}

