/** The codes the calls of "rtcMedia" reject with. */
enum class RtcMediaCode(override val code: String) : PluginCode {
    DENIED("denied"),
    NOT_FOUND("notFound"),
    FAILED("failed"),
}

/** The events of "rtcMedia": what the plugin sends the app. Any thread. */
class RtcMediaEvents(private val channel: PluginEmit) {
    /** A device was plugged in or removed (a headset, a camera). */
    fun deviceChange() = channel.emit("deviceChange", null)

    /** A local track ended on its own: the OS took the device (a call came in, the camera was claimed). */
    fun trackEnded(trackId: String) {
        val w = PackedWriter()
        w.beginObject()
        w.key("trackId"); w.string(trackId)
        w.end()
        this.channel.emit("trackEnded", w.bytes())
    }
}

/**
 * The devices: capture, the device list, the audio route. One session for the app.
 *
 * What the plugin implements. A call arrives on the main thread; its reply is settled exactly
 * once, now or later.
 */
interface RtcMediaPlugin {
    /**
     * Capture: prompts for the permissions it needs, resolves with a stream of the new tracks.
     * Rejects with DENIED / NOT_FOUND / FAILED.
     */
    fun getUserMedia(constraints: MediaConstraints, reply: Reply<StreamInfo, RtcMediaCode>)

    /** The devices the host can capture with (labels need a granted permission on the web). */
    fun enumerateDevices(reply: Reply<List<DeviceInfo>, RtcMediaCode>)

    /**
     * A disabled track sends silence / black frames and stays in every connection.
     * Rejects with NOT_FOUND.
     */
    fun setTrackEnabled(trackId: String, enabled: Boolean, reply: Reply<Unit, RtcMediaCode>)

    /**
     * Re-aim a local video track: the other camera, another size or rate. The track and its id
     * stay; every connection keeps sending it.
     * Rejects with NOT_FOUND / FAILED.
     */
    fun applyConstraints(trackId: String, constraints: VideoConstraints, reply: Reply<Unit, RtcMediaCode>)

    /** Rejects with NOT_FOUND. */
    fun getTrackSettings(trackId: String, reply: Reply<TrackSettings, RtcMediaCode>)

    /**
     * End a track: the device is released once no track of it is left, every sender of it goes
     * quiet, the id is forgotten. A no-op for an unknown id.
     */
    fun stopTrack(trackId: String, reply: Reply<Unit, RtcMediaCode>)

    /**
     * Route the audio of the call: the earpiece (the default while a wired or Bluetooth headset is
     * not connected) or the loudspeaker. A no-op on the web.
     */
    fun setAudioOutput(output: AudioOutput, reply: Reply<Unit, RtcMediaCode>)

    /** The session closed (the app's close, the world's teardown): stop what it started. */
    fun close() {}
}

object RtcMediaChannel {
    /** What the halves register under. */
    const val NAME = "rtcMedia"

    /** The contract's version: the highest `@since` of its members. */
    const val VERSION = 1

    /** Register the service: `make` builds one session from its params. It must be cheap — no
     *  prompt, no I/O: that belongs to the first call that needs it. */
    fun register(engine: LecodesEngine, make: (params: RtcMediaParams, events: RtcMediaEvents) -> RtcMediaPlugin) {
        engine.registerService(NAME, VERSION) { params, channel ->
            val plugin = make(RtcMediaParams.read(Wire.reader(params)) ?: RtcMediaParams(), RtcMediaEvents { event, packed -> channel.emitPacked(event, packed) })
            Services.Instance(onCall = { call -> RtcMediaGlue.call(plugin, call.method, call.reader(), call) }, onClose = { plugin.close() })
        }
    }
}

/** Reads a call off the wire and hands it to the plugin; a malformed call never reaches it. */
internal object RtcMediaGlue {
    fun call(plugin: RtcMediaPlugin, method: String, r: PackedReader, settle: ChannelSettle) {
        val n = r.beginArray()   // the arguments, in their order
        when (method) {
            "getUserMedia" -> {
                val a0 = (if (0 < n) MediaConstraints.read(r) else null) ?: return settle.reject("bad arguments — RtcMedia.getUserMedia: constraints")
                plugin.getUserMedia(a0, Reply<StreamInfo, RtcMediaCode>(settle) { v, w -> v.write(w) })
            }
            "enumerateDevices" -> {
                plugin.enumerateDevices(Reply<List<DeviceInfo>, RtcMediaCode>(settle) { v, w ->
                    w.beginArray()
                    for (v1 in v) { v1.write(w) }
                    w.end()
