            }
            "setTrackEnabled" -> {
                val a0 = (if (0 < n) r.string() else null) ?: return settle.reject("bad arguments — RtcMedia.setTrackEnabled: trackId")
                val a1 = (if (1 < n) r.bool() else null) ?: return settle.reject("bad arguments — RtcMedia.setTrackEnabled: enabled")
                plugin.setTrackEnabled(a0, a1, Reply<Unit, RtcMediaCode>(settle, null))
            }
            "applyConstraints" -> {
                val a0 = (if (0 < n) r.string() else null) ?: return settle.reject("bad arguments — RtcMedia.applyConstraints: trackId")
                val a1 = (if (1 < n) VideoConstraints.read(r) else null) ?: return settle.reject("bad arguments — RtcMedia.applyConstraints: constraints")
                plugin.applyConstraints(a0, a1, Reply<Unit, RtcMediaCode>(settle, null))
            }
            "getTrackSettings" -> {
                val a0 = (if (0 < n) r.string() else null) ?: return settle.reject("bad arguments — RtcMedia.getTrackSettings: trackId")
                plugin.getTrackSettings(a0, Reply<TrackSettings, RtcMediaCode>(settle) { v, w -> v.write(w) })
            }
            "stopTrack" -> {
                val a0 = (if (0 < n) r.string() else null) ?: return settle.reject("bad arguments — RtcMedia.stopTrack: trackId")
                plugin.stopTrack(a0, Reply<Unit, RtcMediaCode>(settle, null))
            }
            "setAudioOutput" -> {
                val a0 = (if (0 < n) AudioOutput.read(r) else null) ?: return settle.reject("bad arguments — RtcMedia.setAudioOutput: output")
                plugin.setAudioOutput(a0, Reply<Unit, RtcMediaCode>(settle, null))
            }
            else -> settle.reject("Unknown method: $method")
        }
    }
}

