/** The codes the calls of "rtcPeerConnection" reject with. */
enum class RtcPeerConnectionCode(override val code: String) : PluginCode {
    FAILED("failed"),
    CLOSED("closed"),
    NOT_FOUND("notFound"),
}

/** The events of "rtcPeerConnection": what the plugin sends the app. Any thread. */
class RtcPeerConnectionEvents(private val channel: PluginEmit) {
