        val w = PackedWriter()
        w.beginObject()
        w.key("candidate")
        candidate.let { v0 -> if (v0 != null) v0.write(w) else w.nil() }
        w.end()
        this.channel.emit("iceCandidate", w.bytes())
    }

    fun signalingStateChange(state: SignalingState) {
        val w = PackedWriter()
        w.beginObject()
        w.key("state"); w.string(state.wire)
        w.end()
        this.channel.emit("signalingStateChange", w.bytes())
    }

    fun iceGatheringStateChange(state: IceGatheringState) {
        val w = PackedWriter()
        w.beginObject()
        w.key("state"); w.string(state.wire)
        w.end()
        this.channel.emit("iceGatheringStateChange", w.bytes())
    }

    fun iceConnectionStateChange(state: IceConnectionState) {
        val w = PackedWriter()
        w.beginObject()
        w.key("state"); w.string(state.wire)
        w.end()
        this.channel.emit("iceConnectionStateChange", w.bytes())
    }

    fun connectionStateChange(state: PeerConnectionState) {
        val w = PackedWriter()
        w.beginObject()
        w.key("state"); w.string(state.wire)
        w.end()
        this.channel.emit("connectionStateChange", w.bytes())
    }

    /**
     * A remote track arrived: the receiver's track of `transceiverId`, in the streams the other
     * side put it in.
     */
    fun track(track: TrackInfo, streamIds: List<String>, transceiverId: String) {
        val w = PackedWriter()
        w.beginObject()
        w.key("track"); track.write(w)
        w.key("streamIds")
        w.beginArray()
        for (v0 in streamIds) { w.string(v0) }
        w.end()
        w.key("transceiverId"); w.string(transceiverId)
        w.end()
        this.channel.emit("track", w.bytes())
    }

    /** A received track went mute (nothing arrives) or came back. */
    fun trackMute(trackId: String, muted: Boolean) {
        val w = PackedWriter()
        w.beginObject()
        w.key("trackId"); w.string(trackId)
        w.key("muted"); w.bool(muted)
        w.end()
        this.channel.emit("trackMute", w.bytes())
    }

    /** A received track ended: the other side removed it, or the connection closed. */
    fun trackEnded(trackId: String) {
        val w = PackedWriter()
        w.beginObject()
        w.key("trackId"); w.string(trackId)
        w.end()
        this.channel.emit("trackEnded", w.bytes())
    }

    /** The other side opened a data channel. */
    fun dataChannel(payload: DataChannelInfo) {
        val w = PackedWriter()
        payload.write(w)
        channel.emit("dataChannel", w.bytes())
    }

    fun dataChannelStateChange(id: String, state: DataChannelState) {
        val w = PackedWriter()
        w.beginObject()
        w.key("id"); w.string(id)
        w.key("state"); w.string(state.wire)
        w.end()
        this.channel.emit("dataChannelStateChange", w.bytes())
    }

    /** One message: `text` for a string, `binary` for bytes — exactly one of the two. */
    fun dataChannelMessage(id: String, text: String? = null, binary: ByteArray? = null) {
        val w = PackedWriter()
        w.beginObject()
        w.key("id"); w.string(id)
        text?.let { v -> w.key("text"); w.string(v) }
        binary?.let { v -> w.key("binary"); w.bytes(v) }
        w.end()
        this.channel.emit("dataChannelMessage", w.bytes())
    }

    fun dataChannelError(id: String, message: String) {
        val w = PackedWriter()
        w.beginObject()
        w.key("id"); w.string(id)
        w.key("message"); w.string(message)
        w.end()
        this.channel.emit("dataChannelError", w.bytes())
    }

    /** The buffered amount fell to the threshold or under it. */
    fun dataChannelBufferedAmountLow(id: String) {
        val w = PackedWriter()
        w.beginObject()
        w.key("id"); w.string(id)
        w.end()
        this.channel.emit("dataChannelBufferedAmountLow", w.bytes())
    }
}

/**
 * One RTCPeerConnection: a session, created with its configuration, closed by the SDK's close().
 *
 * What the plugin implements. A call arrives on the main thread; its reply is settled exactly
 * once, now or later.
 */
interface RtcPeerConnectionPlugin {
    /** Rejects with FAILED / CLOSED. */
    fun createOffer(options: OfferOptions?, reply: Reply<SessionDescription, RtcPeerConnectionCode>)

    /** Rejects with FAILED / CLOSED. */
    fun createAnswer(reply: Reply<SessionDescription, RtcPeerConnectionCode>)

    /**
     * Without a description: the implicit form — an answer when a remote offer is pending, an
     * offer otherwise. Resolves with the description now in force (the one to signal).
     * Rejects with FAILED / CLOSED.
     */
    fun setLocalDescription(description: SessionDescription?, reply: Reply<SessionDescription, RtcPeerConnectionCode>)

    /** Rejects with FAILED / CLOSED. */
    fun setRemoteDescription(description: SessionDescription, reply: Reply<Unit, RtcPeerConnectionCode>)

    /**
     * Without a candidate: the end of the remote candidates.
     * Rejects with FAILED / CLOSED.
     */
    fun addIceCandidate(candidate: IceCandidate?, reply: Reply<Unit, RtcPeerConnectionCode>)

    /** The next offer carries new ICE credentials. */
    fun restartIce(reply: Reply<Unit, RtcPeerConnectionCode>)

    /** Rejects with FAILED. */
    fun setConfiguration(configuration: RtcConfiguration, reply: Reply<Unit, RtcPeerConnectionCode>)

    /**
     * Send a local track, in the streams named (one is made up when none is).
     * Rejects with NOT_FOUND / FAILED / CLOSED.
     */
    fun addTrack(trackId: String, streamIds: List<String>?, reply: Reply<SenderInfo, RtcPeerConnectionCode>)

    /** Rejects with NOT_FOUND / CLOSED. */
    fun removeTrack(senderId: String, reply: Reply<Unit, RtcPeerConnectionCode>)

    /**
     * Swap what a sender sends without renegotiating; null = send nothing.
     * Rejects with NOT_FOUND / FAILED / CLOSED.
     */
    fun replaceTrack(senderId: String, trackId: String?, reply: Reply<Unit, RtcPeerConnectionCode>)

    /** Rejects with NOT_FOUND. */
    fun getSenderParameters(senderId: String, reply: Reply<SenderParameters, RtcPeerConnectionCode>)

    /**
     * The encodings' active / bitrate / scale; the layers themselves are set at addTransceiver.
     * Rejects with NOT_FOUND / FAILED.
     */
    fun setSenderParameters(senderId: String, parameters: SenderParameters, reply: Reply<Unit, RtcPeerConnectionCode>)

    /** Rejects with NOT_FOUND / FAILED / CLOSED. */
    fun addTransceiver(kind: MediaKind, options: TransceiverInit?, reply: Reply<TransceiverInfo, RtcPeerConnectionCode>)

    fun getTransceivers(reply: Reply<List<TransceiverInfo>, RtcPeerConnectionCode>)

    /** Rejects with NOT_FOUND / FAILED. */
    fun setTransceiverDirection(transceiverId: String, direction: TransceiverDirection, reply: Reply<Unit, RtcPeerConnectionCode>)

    /** Rejects with NOT_FOUND. */
    fun stopTransceiver(transceiverId: String, reply: Reply<Unit, RtcPeerConnectionCode>)

    /**
     * The RTCStatsReport as an object: the stats id → the stats object (`type`, `timestamp` in ms,
     * the fields of its type). For one track's senders / receivers when `trackId` is given.
     */
    fun getStats(trackId: String?, reply: Reply<Any, RtcPeerConnectionCode>)

    /** Rejects with FAILED / CLOSED. */
    fun createDataChannel(label: String, options: DataChannelInit?, reply: Reply<DataChannelInfo, RtcPeerConnectionCode>)

    /** Rejects with NOT_FOUND / CLOSED. */
    fun sendText(channelId: String, text: String, reply: Reply<Unit, RtcPeerConnectionCode>)

    /** Rejects with NOT_FOUND / CLOSED. */
    fun sendBinary(channelId: String, data: ByteArray, reply: Reply<Unit, RtcPeerConnectionCode>)

    /**
     * Bytes queued and not yet sent.
     * Rejects with NOT_FOUND.
     */
    fun getBufferedAmount(channelId: String, reply: Reply<Double, RtcPeerConnectionCode>)

    /** Rejects with NOT_FOUND. */
    fun setBufferedAmountLowThreshold(channelId: String, threshold: Double, reply: Reply<Unit, RtcPeerConnectionCode>)

    /** A no-op for an unknown id. */
    fun closeDataChannel(channelId: String, reply: Reply<Unit, RtcPeerConnectionCode>)

    /** The session closed (the app's close, the world's teardown): stop what it started. */
    fun close() {}
}

object RtcPeerConnectionChannel {
