    val view: android.view.View

    /**
     * Draw another track; null = black.
     * Rejects with NOT_FOUND.
     */
    fun setTrack(trackId: String?, reply: Reply<Unit, RtcVideoCode>)

    fun setObjectFit(fit: ObjectFit, reply: Reply<Unit, RtcVideoCode>)

    fun setMirror(mirror: Boolean, reply: Reply<Unit, RtcVideoCode>)

    /** The instance goes (the world swapped): release the hardware. */
    fun destroy() {}
}

object RtcVideoChannel {
    /** What the halves register under. */
    const val NAME = "rtcVideo"

    /** The contract's version: the highest `@since` of its members. */
    const val VERSION = 1

    /** Register the view: `make` builds one instance from its params. */
    fun register(engine: LecodesEngine, make: (params: RtcVideoParams, events: RtcVideoEvents) -> RtcVideoPlugin) {
        engine.registerView(NAME, VERSION) { params, channel ->
            val plugin = make(RtcVideoParams.read(Wire.reader(params)) ?: RtcVideoParams(), RtcVideoEvents { event, packed -> channel.emitPacked(event, packed) })
            NativeViews.Instance(plugin.view, onCall = { call -> RtcVideoGlue.call(plugin, call.method, call.reader(), call) }, onDestroy = { plugin.destroy() })
        }
    }
}

/** Reads a call off the wire and hands it to the plugin; a malformed call never reaches it. */
internal object RtcVideoGlue {
    fun call(plugin: RtcVideoPlugin, method: String, r: PackedReader, settle: ChannelSettle) {
        val n = r.beginArray()   // the arguments, in their order
        when (method) {
            "setTrack" -> {
                val a0 = if (0 < n && !r.isNull()) (r.string() ?: return settle.reject("bad arguments — RtcVideo.setTrack: trackId")) else { if (0 < n) r.skip(); null }
                plugin.setTrack(a0, Reply<Unit, RtcVideoCode>(settle, null))
            }
            "setObjectFit" -> {
                val a0 = (if (0 < n) ObjectFit.read(r) else null) ?: return settle.reject("bad arguments — RtcVideo.setObjectFit: fit")
                plugin.setObjectFit(a0, Reply<Unit, RtcVideoCode>(settle, null))
            }
            "setMirror" -> {
                val a0 = (if (0 < n) r.bool() else null) ?: return settle.reject("bad arguments — RtcVideo.setMirror: mirror")
                plugin.setMirror(a0, Reply<Unit, RtcVideoCode>(settle, null))
            }
            else -> settle.reject("Unknown method: $method")
        }
    }
}
